{
  "case_id": "xsu_sg_004_multiple_impairments",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret har det rigtige udgangspunkt (kun de ansøgte funktionsnedsættelser) og den samlede vurdering. Men det udelader, at en anden varig funktionsnedsættelse kan inddrages under sagsbehandlingen, hvis ansøgeren ønsker det og indsender fyldestgørende dokumentation. Det gør konklusionen ufuldstændig. Desuden indeholder svaret den sidste sætning om, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret, og påstanden om, at vurderingen bygger på 'aktuelle symptomer'. Disse udsagn er ikke understøttet af de udleverede passager."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Tre af fire kritiske elementer er med: samlet vurdering, angivelse og dokumentation, samt udgangspunktet. Det fjerde element mangler: senere inddragelse af en anden varig funktionsnedsættelse på ansøgerens ønske og med fyldestgørende dokumentation, der opfylder minimumskravene. Det understøttende punkt om, at journalomtale ikke er nok, mangler også."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilke funktionsnedsættelser Udbetaling Danmark vurderer: de ansøgte, og hvis der er flere, samlet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver Vejledning nr. 10157 (VEJ nr 10157 af 05/10/2026) som kilde, og påstandene er knyttet til den via nummerhenvisninger. Henvisningerne er dog kun tal, ikke afsnit."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning 10157 findes inden for den frosne kildeafgrænsning og er en autoritativ og aktuel kilde, som svaret bruger til netop dette emne."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De fleste hovedpåstande støttes af afsnit 3.4.1.2 og 3.5. Men påstanden om, at vurderingen sker 'på baggrund af de lægefaglige oplysninger og de aktuelle symptomer, som er beskrevet i materialet', og citatet om, at funktionsnedsættelsen skal være 'velbeskrevet og lægefagligt dokumenteret', står ikke i de udleverede passager. Påstanden om, at myndigheden vurderer 'den samlede betydning ... for erhvervsevnen', går også ud over passagen, som taler om samlet vurdering af, om betingelserne er opfyldt."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en regel om, at vurderingen sker ud fra 'aktuelle symptomer', og at funktionsnedsættelsen skal være 'velbeskrevet'. Ingen af delene har støtte i det udleverede materiale. Aktualitetskravet i § 37, stk. 4 gælder dokumentationen og ikke symptomer."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Udgangspunktet er bevaret ('som udgangspunkt'). Men undtagelsen om senere inddragelse, forudsat ønske og fyldestgørende dokumentation, mangler. Det samme gælder, at journalomtale ikke er nok. Den krævede kvalifikation er derfor ikke fuldt bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "De trin, der er givet, hænger sammen: udgangspunktet om ansøgte funktionsnedsættelser, samlet vurdering ved flere, og ansøgeren bør angive og dokumentere. Konklusionen følger af dem, selv om den er ufuldstændig."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Som udgangspunkt' og 'bør' gengiver kilden rimeligt. Svaret gør ikke skøn eller undtagelser absolutte. Den manglende undtagelse hører under C08."
    }
  },
  "xhaile_coverage": {
    "A16": {
      "label": "yes",
      "reason": "Svaret siger, at Udbetaling Danmark foretager en samlet vurdering ved flere funktionsnedsættelser, og at der skal dokumenteres for dem alle."
    },
    "A24": {
      "label": "yes",
      "reason": "Svaret siger, at kun de funktionsnedsættelser, ansøgeren selv søger på, som udgangspunkt vurderes, og at ansøgeren bør angive dem. Eksemplet om journalomtale af andre forhold er ikke med, men kernen er dækket."
    },
    "A25": {
      "label": "no",
      "reason": "Svaret nævner ikke, at ansøgeren under sagsbehandlingen kan få en anden varig funktionsnedsættelse inddraget ved at indsende fyldestgørende dokumentation og oplyse, at vedkommende ønsker det. Det nævner heller ikke, at inddragelse sker på ansøgerens initiativ."
    }
  },
  "overall_notes": "Svaret rammer udgangspunktet og den samlede vurdering rigtigt og har en identificerbar kilde. Det mangler dog helt reglen om senere inddragelse af yderligere funktionsnedsættelser og den dokumentationsbetingelse, der hører til. Desuden tilføjer det ustøttede udsagn om 'aktuelle symptomer', 'velbeskrevet' og 'erhvervsevne'. Derfor fejler C01, C02, C06, C07 og C08."
}

